```go
// Package pool runs work on a bounded number of goroutines.
package pool

import (
	"context"
	"fmt"
	"sync"
)

// IndexError reports which input failed.
type IndexError struct {
	Index int
	Err   error
}

func (e *IndexError) Error() string { return fmt.Sprintf("pool: input %d: %v", e.Index, e.Err) }
func (e *IndexError) Unwrap() error { return e.Err }

// Map ... (keep the same documentation)
func Map[T, R any](ctx context.Context, in []T, workers int, fn func(context.Context, T) (R, error)) ([]R, error) {
	if workers < 1 {
		workers = 1
	}
	type result struct {
		r   R
		err error
		i   int
	}
	jobs := make(chan int)
	results := make(chan result)
	stop := make(chan struct{})
	var stopOnce sync.Once
	stopAll := func() { stopOnce.Do(func() { close(stop) }) }

	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				r, err := fn(ctx, in[i])
				results <- result{r, err, i}
			}
		}()
	}
	// Dispatcher: stop issuing work on stop.
	go func() {
		defer close(jobs)
		for i := range in {
			select {
			case jobs <- i:
			case <-stop:
				return
			}
		}
	}()
	// Closer: close results once all workers have exited.
	go func() {
		wg.Wait()
		close(results)
	}()

	out := make([]R, len(in))
	filled := 0
	firstErrIdx := -1
	var firstErr error
	cancelled := false
forNext:
	for {
		select {
		case res, ok := <-results:
			if !ok {
				break forNext // all workers done
			}
			if res.err != nil {
				if firstErrIdx < 0 || res.i < firstErrIdx {
					firstErrIdx, firstErr = res.i, res.err
				}
				stopAll()
				continue
			}
			out[res.i] = res.r
			filled++
		case <-ctx.Done():
			cancelled = true
			stopAll()
		}
	}
	switch {
	case firstErrIdx >= 0:
		return nil, &IndexError{Index: firstErrIdx, Err: firstErr}
	case cancelled:
		return nil, ctx.Err()
	}
	return out, nil
}
```

