	go func() {
		wg.Wait()
		close(results)
	}()

	out := make([]R, len(in))
	firstErrIdx := -1
	var firstErr error
	cancelled := false
forNext:
	for {
		select {
		case res, ok := <-results:
			// When results is closed, every worker has exited, so it is
			// safe to return.
			if !ok {
				break forNext
			}
			if res.err != nil {
				if firstErrIdx < 0 || res.i < firstErrIdx {
