// TestOrdering verifies out[i] is the result for in[i] even when results
// arrive out of order under concurrency.
func TestOrdering(t *testing.T) {
	in := make([]int, 500)
	for i := range in {
		in[i] = i
	}
	done := make(chan struct{})
	var out []int
	var err error
	go func() {
		out, err = Map(context.Background(), in, 16, func(_ context.Context, x int) (int, error) {
			// Make results arrive in an order unrelated to input order.
			time.Sleep(time.Duration(500-x) * time.Microsecond)
			return x * 2, nil
		})
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("Map hung")
	}
	if err != nil || len(out) != len(in) {
		t.Fatalf("out=%v err=%v", out, err)
	}
	for i, r := range out {
		if r != in[i]*2 {
			t.Fatalf("out[%d]=%d, want %d", i, r, in[i]*2)
		}
	}
}

// TestCancellation verifies Map returns promptly with ctx.Err() after
// cancellation and does not leak goroutines.
func TestCancellation(t *testing.T) {
	before := runtime.NumGoroutine()
	ctx, cancel := context.WithCancel(context.Background())
	in := make([]int, 20)
	for i := range in {
		in[i] = i
	}
	var called atomic.Int64
	go func() {
		time.Sleep(20 * time.Millisecond)
		cancel()
	}()
	done := make(chan struct{})
	var err error
	start := time.Now()
	go func() {
		_, err = Map(ctx, in, 4, func(c context.Context, x int) (int, error) {
			called.Add(1)
			<-c.Done() // long-running work that respects ctx
			return 0, nil
		})
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("Map did not return after ctx cancellation")
	}
	if time.Since(start) > 3*time.Second {
		t.Fatalf("Map took %v after cancellation", time.Since(start))
	}
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("err = %v, want context.Canceled", err)
	}
	// No goroutine leaks: when Map returns, all workers must be gone.
	deadline := time.Now().Add(5 * time.Second)
	for {
		if runtime.NumGoroutine() <= before {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("goroutine leak: %d now, was %d", runtime.NumGoroutine(), before)
		}
		time.Sleep(10 * time.Millisecond)
	}
	if got := called.Load(); got > 8 {
		t.Fatalf("new work started after cancellation: %d calls", got)
	}
}

// TestLowestErrorIndex verifies Map reports the failing input with the lowest
// index, not the error that happened to arrive first.
func TestLowestErrorIndex(t *testing.T) {
	errLate := errors.New("late failure")
	errEarly := errors.New("early failure")
	for k := 0; k < 10; k++ {
		_, err := Map(context.Background(), []int{0, 1, 2, 3, 4, 5, 6, 7}, 2, func(_ context.Context, x int) (int, error) {
			switch x {
			case 6:
				time.Sleep(10 * time.Millisecond) // fails fast
				return 0, errLate
			case 1:
				time.Sleep(80 * time.Millisecond) // fails slow
				return 0, errEarly
			}
			return x, nil
		})
		var ie *IndexError
		if !errors.As(err, &ie) {
			t.Fatalf("err = %v, want *IndexError", err)
		}
		if ie.Index != 1 {
			t.Fatalf("Index = %d, want 1 (err=%v)", ie.Index, ie.Err)
		}
		if !errors.Is(err, errEarly) {
			t.Fatalf("wrapped err = %v, want %v", ie.Err, errEarly)
		}
	}
}

// TestErrorStopsNewWork verifies that once a call fails, Map stops starting
// new work and the running calls all finish.
func TestErrorStopsNewWork(t *testing.T) {
	in := make([]int, 1000)
	for i := range in {
		in[i] = i
	}
	var started, finished atomic.Int64
	var mu sync.Mutex
	boom := errors.New("boom")
	out, err := Map(context.Background(), in, 8, func(_ context.Context, x int) (int, error) {
		started.Add(1)
		if x == 0 {
			return 0, boom // fails immediately
		}
		time.Sleep(100 * time.Millisecond)
		finished.Add(1)
		return x, nil
	})
	if out != nil {
		t.Fatalf("out = %v, want nil", out)
	}
	var ie *IndexError
	if !errors.As(err, &ie) || ie.Index != 0 || !errors.Is(err, boom) {
		t.Fatalf("err = %v, want IndexError{0, boom}", err)
	}
	// No new work after the error: the started count must be stable.
	s1, f1 := started.Load(), finished.Load()
	time.Sleep(200 * time.Millisecond)
	if s2, f2 := started.Load(), finished.Load(); s2 != s1 || f2 != f1 {
		mu.Lock()
		t.Fatalf("work still in flight: started %d->%d, finished %d->%d", s1, s2, f1, f2)
		mu.Unlock()
	}
	if s1 > 64 {
		t.Fatalf("too much new work started after failure: %d", s1)
	}
}

